package vn.edu.crs.courseservice.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.nio.charset.StandardCharsets; import java.util.List; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtAuthFilter extends OncePerRequestFilter { @Value("${jwt.secret}") String secret; protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer "))try{SecretKey k=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8)); Claims x=Jwts.parser().verifyWith(k).build().parseSignedClaims(h.substring(7)).getPayload(); String role=x.get("role",String.class); SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(x.getSubject(),null,List.of(new SimpleGrantedAuthority("ROLE_"+role))));}catch(Exception ignored){SecurityContextHolder.clearContext();} c.doFilter(r,s);}}
